public static func inspect(
    textView: UITextView,
    searchRanges: [NSRange],
    currentLocator: String?,
    renderGeneration: Int
) -> RenderedHighlightSnapshot {
    guard let attributedString = textView.attributedText, attributedString.length > 0 else {
        return RenderedHighlightSnapshot(
            searchHighlightCount: 0,
            annotationHighlightCount: 0,
            segmentSelectionCount: 0,
            totalHighlights: 0,
            locator: currentLocator,
            renderGeneration: renderGeneration,
            highlights: []
        )
    }

public static func updateDiagnostics(
    for textView: UITextView,
    searchRanges: [NSRange],
    currentLocator: String?,
    renderGeneration: Int
) {
    let snapshot = inspect(
        textView: textView,
        searchRanges: searchRanges,
        currentLocator: currentLocator,
        renderGeneration: renderGeneration
    )
    let jsonString = snapshot.toJSONString()

    // Both enabled native Reader hosts must expose their actual book text
    // to VoiceOver. The compact phone host previously overwrote it with
    // diagnostic JSON. Keep only the immutable flags-off baseline behavior;
    // structured diagnostics retain their existing dedicated child.
    if !ChavrusaTextReaderUI.isEnabled {
        textView.accessibilityValue = jsonString
    }

    let subview: UIView
    if let existing = textView.subviews.first(where: { $0.accessibilityIdentifier == diagnosticsAccessibilityIdentifier }) {
        subview = existing
    } else {
        let view = UIView(frame: CGRect(x: 0, y: 0, width: 1, height: 1))
        view.accessibilityIdentifier = diagnosticsAccessibilityIdentifier
        view.isAccessibilityElement = true
        view.isUserInteractionEnabled = false
        textView.addSubview(view)
        subview = view
    }
    subview.accessibilityValue = jsonString
    subview.accessibilityLabel = "searchHighlights:\(snapshot.searchHighlightCount)"
}

func updateUIView(_ uiView: UIView, context: Context) {
    guard let textView = uiView.subviews.first as? iOSCustomIbarotTextView else { return }

    context.coordinator.parent = self
    updateTextAlignmentAndSemantics(for: textView)
    setupViewModelClosure(for: textView, context: context)

    if context.coordinator.lastBackgroundColorIndex != state.backgroundColorIndex {
        context.coordinator.lastBackgroundColorIndex = state.backgroundColorIndex
        if let tlm = textView.textLayoutManager {
            tlm.invalidateLayout(for: tlm.documentRange)
            textView.setNeedsDisplay()
        }
    }

    let rendered = resolveRenderedContent(textView: textView, context: context)

    #if DEBUG
    ReaderRenderedHighlightInspector.updateDiagnostics(
        for: textView,
        searchRanges: rendered.searchRanges,
        currentLocator: viewModel.currentLocator?.persistenceKey,
        renderGeneration: context.coordinator.renderGeneration
    )
